INSERT OR REPLACE INTO person_setting (id, tag, value, value_text, person) VALUES
  (90001, 'paradigm', 'text', '<p>Tech over truth, but warrants matter. Extend your impacts through the final speech. I flow on paper.</p>', 90001),
  (90002, 'paradigm', 'text', '<p>Lay judge. Speak clearly, explain your evidence and weigh at the end.</p>', 90002),
  (90003, 'paradigm', 'text', '<p>Former LD debater. Frameworks are fine; tell me how the value and criterion filter the round.</p>', 90003),
  (90004, 'paradigm', 'text', '<p>Policy background. Comfortable with speed; clash beats blippy extensions.</p>', 90004),
  (9000001, 'paradigm', 'text', '<p>Theory is fine when there is real abuse. Disclosure arguments need a screenshot.</p>', 9000003),
  (9000002, 'paradigm', 'text', '<p>Speech coach: I rank on structure, delivery and how well you know your audience.</p>', 9000006),
  (9000003, 'paradigm', 'text', '<p>Former LD debater. Frameworks are fine; tell me how the value and criterion filter the round.</p>', 9000009),
  (9000004, 'paradigm', 'text', '<p>I vote on the flow, but I need a clear ballot story in the last speech.</p>', 9000012),
  (9000005, 'paradigm', 'text', '<p>Kritiks are welcome; explain the alternative and the role of the ballot.</p>', 9000015),
  (9000006, 'paradigm', 'text', '<p>Lay judge. Speak clearly, explain your evidence and weigh at the end.</p>', 9000018),
